package io.invenlio.procurement;
import io.invenlio.catalog.CatalogInventoryLookup;import io.invenlio.organization.*;import io.invenlio.warehouse.WarehouseAvailability;import java.math.*;import java.sql.*;import java.time.*;import java.util.Currency;import java.util.List;import java.util.Optional;import java.util.Set;import java.util.UUID;import org.springframework.context.ApplicationEventPublisher;import org.springframework.dao.DataIntegrityViolationException;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service class PurchaseOrderService implements PurchaseOrderAccess{private final AuthorizationService auth;private final AuditTrail audit;private final JdbcTemplate db;private final SupplierEligibilityQuery suppliers;private final CatalogInventoryLookup catalog;private final WarehouseAvailability warehouses;private final ApplicationEventPublisher events;PurchaseOrderService(AuthorizationService a,AuditTrail t,JdbcTemplate d,SupplierEligibilityQuery s,CatalogInventoryLookup c,WarehouseAvailability w,ApplicationEventPublisher e){auth=a;audit=t;db=d;suppliers=s;catalog=c;warehouses=w;events=e;}
 @Transactional OrderView create(Create c){var a=auth.require(Permission.PURCHASE_ORDER_CREATE);var s=supplier(a.tenantId(),c.supplierId);if(!s.status.equals("ACTIVE"))throw err("SUPPLIER_NOT_PURCHASE_ELIGIBLE","Supplier must be active");var w=warehouses.findActiveWarehouse(a.tenantId(),c.warehouseId).orElseThrow(()->err("PURCHASE_ORDER_WAREHOUSE_INVALID","Warehouse must be active in this tenant"));String currency=currency(c.currency==null?s.currency:c.currency);if(!currency.equals(s.currency))throw err("PURCHASE_ORDER_CURRENCY_MISMATCH","PO currency must match supplier currency");long sequence=db.queryForObject("INSERT INTO purchase_order_number_counters(tenant_id,order_year,next_value) VALUES(?,?,2) ON CONFLICT(tenant_id,order_year) DO UPDATE SET next_value=purchase_order_number_counters.next_value+1 RETURNING next_value-1",Long.class,a.tenantId(),Year.now(ZoneOffset.UTC).getValue());String number="PO-"+Year.now(ZoneOffset.UTC).getValue()+"-"+String.format("%06d",sequence);UUID id=UUID.randomUUID();db.update("INSERT INTO purchase_orders(id,tenant_id,supplier_id,warehouse_id,purchase_order_number,status,supplier_number_snapshot,supplier_name_snapshot,supplier_legal_name_snapshot,warehouse_code_snapshot,warehouse_name_snapshot,currency,payment_terms_days,expected_delivery_date,supplier_reference,internal_note,supplier_note,subtotal,total,created_by,created_at,updated_at,version)VALUES(?,?,?,?,?,'DRAFT',?,?,?,?,?,?,?,?,?,?,?,0,0,?,now(),now(),0)",id,a.tenantId(),s.id,c.warehouseId,number,s.number,s.name,s.legalName,w.code(),w.name(),currency,s.paymentTerms,date(c.expectedDeliveryDate),text(c.supplierReference,120),text(c.internalNote,1000),text(c.supplierNote,1000),a.userId());audit.record(a,"PURCHASE_ORDER_CREATED","purchase-order",id.toString());events.publishEvent(new ProcurementEvents.PurchaseOrderCreated(a.tenantId(),id));return detail(a.tenantId(),id);}
 @Transactional OrderView update(UUID id,Update c,long version){var a=auth.require(Permission.PURCHASE_ORDER_UPDATE);lockEditable(a.tenantId(),id);var w=warehouses.findActiveWarehouse(a.tenantId(),c.warehouseId).orElseThrow(()->err("PURCHASE_ORDER_WAREHOUSE_INVALID","Warehouse must be active in this tenant"));changed(db.update("UPDATE purchase_orders SET warehouse_id=?,warehouse_code_snapshot=?,warehouse_name_snapshot=?,expected_delivery_date=?,supplier_reference=?,internal_note=?,supplier_note=?,updated_at=now(),version=version+1 WHERE tenant_id=? AND id=? AND status='DRAFT' AND version=?",c.warehouseId,w.code(),w.name(),date(c.expectedDeliveryDate),text(c.supplierReference,120),text(c.internalNote,1000),text(c.supplierNote,1000),a.tenantId(),id,version));audit.record(a,"PURCHASE_ORDER_UPDATED","purchase-order",id.toString());return detail(a.tenantId(),id);}
 @Transactional LineView addLine(UUID poId,LineCommand c){var a=auth.require(Permission.PURCHASE_ORDER_UPDATE);OrderView po=lockEditable(a.tenantId(),poId);var p=suppliers.findEligibleProduct(a.tenantId(),c.supplierProductId).orElseThrow(()->err("SUPPLIER_PRODUCT_NOT_PURCHASE_ELIGIBLE","Supplier product is not eligible"));if(!p.supplierId().equals(po.supplierId))throw err("PURCHASE_ORDER_SUPPLIER_MISMATCH","Supplier product belongs to another supplier");if(p.unitCost()==null)throw err("SUPPLIER_PRODUCT_NOT_PURCHASE_ELIGIBLE","Supplier product has no unit cost");if(!p.currency().equals(po.currency))throw err("PURCHASE_ORDER_CURRENCY_MISMATCH","Supplier product currency differs from PO");BigDecimal q=positive(c.orderedQuantity,"INVALID_PURCHASE_QUANTITY");if(p.minimumOrderQuantity()!=null&&q.compareTo(p.minimumOrderQuantity())<0)throw err("MINIMUM_ORDER_QUANTITY_NOT_MET","Quantity is below MOQ");if(p.orderMultiple()!=null&&q.remainder(p.orderMultiple()).compareTo(BigDecimal.ZERO)!=0)throw err("ORDER_MULTIPLE_VIOLATION","Quantity is not an order multiple");var v=catalog.findInventoryVariant(a.tenantId(),p.variantId()).orElseThrow(()->err("SUPPLIER_PRODUCT_NOT_PURCHASE_ELIGIBLE","Variant is unavailable"));BigDecimal base=scale(q.multiply(p.baseUnitsPerPurchaseUnit()));if(v.discrete()&&base.stripTrailingZeros().scale()>0)throw err("INVALID_PURCHASE_QUANTITY","Discrete base unit requires integral base quantity");BigDecimal subtotal=money(q.multiply(p.unitCost()));int line=db.queryForObject("SELECT COALESCE(max(line_number),0)+1 FROM purchase_order_lines WHERE tenant_id=? AND purchase_order_id=?",Integer.class,a.tenantId(),poId);UUID id=UUID.randomUUID();LocalDate expected=c.expectedDeliveryDate==null?(p.leadTimeDays()==null?po.expectedDeliveryDate:LocalDate.now(ZoneOffset.UTC).plusDays(p.leadTimeDays())):date(c.expectedDeliveryDate);try{db.update("INSERT INTO purchase_order_lines(id,tenant_id,purchase_order_id,supplier_id,supplier_product_id,variant_id,line_number,supplier_sku_snapshot,variant_sku_snapshot,description_snapshot,ordered_quantity,purchase_unit_code,base_units_per_purchase_unit,base_quantity,unit_cost,currency,line_subtotal,expected_delivery_date,created_at,updated_at,version)VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,now(),now(),0)",id,a.tenantId(),poId,po.supplierId,p.supplierProductId(),p.variantId(),line,p.supplierSku(),v.sku(),v.displayName(),q,p.purchaseUnitCode(),p.baseUnitsPerPurchaseUnit(),base,p.unitCost(),p.currency(),subtotal,expected);}catch(Exception e){throw err("PURCHASE_ORDER_LINE_DUPLICATE","Supplier product already exists on PO");}totals(a.tenantId(),poId);audit.record(a,"PURCHASE_ORDER_LINE_ADDED","purchase-order-line",id.toString());return line(a.tenantId(),poId,id);}
 @Transactional LineView updateLine(UUID poId,UUID lineId,LineUpdate c,long version){var a=auth.require(Permission.PURCHASE_ORDER_UPDATE);lockEditable(a.tenantId(),poId);LineView old=line(a.tenantId(),poId,lineId);var p=suppliers.findEligibleProduct(a.tenantId(),old.supplierProductId).orElseThrow(()->err("SUPPLIER_PRODUCT_NOT_PURCHASE_ELIGIBLE","Supplier product is not eligible"));BigDecimal q=positive(c.orderedQuantity,"INVALID_PURCHASE_QUANTITY");if(p.minimumOrderQuantity()!=null&&q.compareTo(p.minimumOrderQuantity())<0)throw err("MINIMUM_ORDER_QUANTITY_NOT_MET","Quantity is below MOQ");if(p.orderMultiple()!=null&&q.remainder(p.orderMultiple()).compareTo(BigDecimal.ZERO)!=0)throw err("ORDER_MULTIPLE_VIOLATION","Quantity is not an order multiple");BigDecimal base=scale(q.multiply(old.baseUnitsPerPurchaseUnit));var v=catalog.findInventoryVariant(a.tenantId(),old.variantId).orElseThrow();if(v.discrete()&&base.stripTrailingZeros().scale()>0)throw err("INVALID_PURCHASE_QUANTITY","Discrete base unit requires integral base quantity");changed(db.update("UPDATE purchase_order_lines SET ordered_quantity=?,base_quantity=?,line_subtotal=?,expected_delivery_date=?,updated_at=now(),version=version+1 WHERE tenant_id=? AND purchase_order_id=? AND id=? AND version=?",q,base,money(q.multiply(old.unitCost)),date(c.expectedDeliveryDate),a.tenantId(),poId,lineId,version));totals(a.tenantId(),poId);audit.record(a,"PURCHASE_ORDER_LINE_UPDATED","purchase-order-line",lineId.toString());return line(a.tenantId(),poId,lineId);}
 @Transactional void removeLine(UUID poId,UUID lineId,long version){var a=auth.require(Permission.PURCHASE_ORDER_UPDATE);lockEditable(a.tenantId(),poId);changed(db.update("DELETE FROM purchase_order_lines WHERE tenant_id=? AND purchase_order_id=? AND id=? AND version=?",a.tenantId(),poId,lineId,version));totals(a.tenantId(),poId);audit.record(a,"PURCHASE_ORDER_LINE_REMOVED","purchase-order-line",lineId.toString());}
 @Transactional OrderView submit(UUID id,long version){var a=auth.require(Permission.PURCHASE_ORDER_UPDATE);lock(a.tenantId(),id);if(db.queryForObject("SELECT count(*) FROM purchase_order_lines WHERE tenant_id=? AND purchase_order_id=?",Integer.class,a.tenantId(),id)==0)throw err("PURCHASE_ORDER_EMPTY","Purchase order requires a line");changed(db.update("UPDATE purchase_orders SET status='SUBMITTED',order_date=CURRENT_DATE,submitted_at=now(),updated_at=now(),version=version+1 WHERE tenant_id=? AND id=? AND status='DRAFT' AND version=?",a.tenantId(),id,version));audit.record(a,"PURCHASE_ORDER_SUBMITTED","purchase-order",id.toString());events.publishEvent(new ProcurementEvents.PurchaseOrderSubmitted(a.tenantId(),id));return detail(a.tenantId(),id);}
 @Transactional OrderView approve(UUID id,long version){var a=auth.require(Permission.PURCHASE_ORDER_APPROVE);changed(db.update("UPDATE purchase_orders SET status='APPROVED',approved_at=now(),approved_by=?,updated_at=now(),version=version+1 WHERE tenant_id=? AND id=? AND status='SUBMITTED' AND version=?",a.userId(),a.tenantId(),id,version));audit.record(a,"PURCHASE_ORDER_APPROVED","purchase-order",id.toString());events.publishEvent(new ProcurementEvents.PurchaseOrderApproved(a.tenantId(),id));return detail(a.tenantId(),id);}
 @Transactional OrderView sent(UUID id,long version){var a=auth.require(Permission.PURCHASE_ORDER_UPDATE);changed(db.update("UPDATE purchase_orders SET status='SENT',sent_at=now(),updated_at=now(),version=version+1 WHERE tenant_id=? AND id=? AND status='APPROVED' AND version=?",a.tenantId(),id,version));audit.record(a,"PURCHASE_ORDER_SENT","purchase-order",id.toString());events.publishEvent(new ProcurementEvents.PurchaseOrderSent(a.tenantId(),id));return detail(a.tenantId(),id);}
 @Transactional OrderView cancel(UUID id,long version,String reason){var a=auth.require(Permission.PURCHASE_ORDER_CANCEL);String why=required(reason,500);changed(db.update("UPDATE purchase_orders SET status='CANCELLED',cancelled_at=now(),cancelled_by=?,cancellation_reason=?,updated_at=now(),version=version+1 WHERE tenant_id=? AND id=? AND status IN('DRAFT','SUBMITTED','APPROVED','SENT') AND version=?",a.userId(),why,a.tenantId(),id,version));audit.record(a,"PURCHASE_ORDER_CANCELLED","purchase-order",id.toString());events.publishEvent(new ProcurementEvents.PurchaseOrderCancelled(a.tenantId(),id));return detail(a.tenantId(),id);}
 @Transactional(readOnly=true)OrderView get(UUID id){var a=auth.require(Permission.PURCHASE_ORDER_READ);return detail(a.tenantId(),id);}@Transactional(readOnly=true)List<OrderView>list(String number,UUID supplier,UUID warehouse,String status,LocalDate createdFrom,LocalDate createdTo,LocalDate expectedFrom,LocalDate expectedTo,String q,int page,int size,String sort){var a=auth.require(Permission.PURCHASE_ORDER_READ);if(page<0||size<1||size>100)throw err("INVALID_PAGINATION","Invalid pagination");String order=switch(sort==null?"createdAt":sort){case"createdAt"->"created_at DESC";case"poNumber"->"purchase_order_number";case"status"->"status";case"expectedDeliveryDate"->"expected_delivery_date NULLS LAST";case"total"->"total";default->throw err("INVALID_SORT","Unsupported sort");};String like=q==null?null:"%"+q.trim().toLowerCase()+"%";return db.query("SELECT id FROM purchase_orders WHERE tenant_id=? AND (?::text IS NULL OR purchase_order_number=?::text) AND (?::uuid IS NULL OR supplier_id=?::uuid) AND (?::uuid IS NULL OR warehouse_id=?::uuid) AND (?::text IS NULL OR status=?::text) AND (?::date IS NULL OR created_at::date>=?::date) AND (?::date IS NULL OR created_at::date<=?::date) AND (?::date IS NULL OR expected_delivery_date>=?::date) AND (?::date IS NULL OR expected_delivery_date<=?::date) AND (?::text IS NULL OR lower(purchase_order_number) LIKE ? OR lower(COALESCE(supplier_reference,'')) LIKE ?) ORDER BY "+order+",id OFFSET ? LIMIT ?",(r,n)->detail(a.tenantId(),(UUID)r.getObject(1)),a.tenantId(),number,number,supplier,supplier,warehouse,warehouse,status,status,createdFrom,createdFrom,createdTo,createdTo,expectedFrom,expectedFrom,expectedTo,expectedTo,like,like,like,page*size,size);}
 @Override@Transactional(readOnly=true)public Optional<ReceivingOrder>findReceivable(UUID tenantId,UUID id){try{OrderView o=detail(tenantId,id);if(!Set.of("APPROVED","SENT").contains(o.status))return Optional.empty();return Optional.of(new ReceivingOrder(o.id,o.number,o.status,o.supplierId,o.warehouseId,o.currency,o.lines.stream().map(l->new ReceivingLine(l.id,l.supplierProductId,l.variantId,l.baseQuantity,catalog.findInventoryVariant(tenantId,l.variantId).map(CatalogInventoryLookup.InventoryVariant::baseUnit).orElse(l.baseUnit()),l.expectedDeliveryDate)).toList()));}catch(ProcurementException e){return Optional.empty();}}
 private OrderView lockEditable(UUID t,UUID id){OrderView o=lock(t,id);if(!o.status.equals("DRAFT"))throw err("PURCHASE_ORDER_NOT_EDITABLE","Only draft purchase orders are editable");return o;}private OrderView lock(UUID t,UUID id){var x=db.query("SELECT id FROM purchase_orders WHERE tenant_id=? AND id=? FOR UPDATE",(r,n)->(UUID)r.getObject(1),t,id);if(x.isEmpty())throw err("PURCHASE_ORDER_NOT_FOUND","Purchase order not found");return detail(t,id);}private OrderView detail(UUID t,UUID id){var x=db.query("SELECT id,purchase_order_number,supplier_id,warehouse_id,status,supplier_number_snapshot,supplier_name_snapshot,supplier_legal_name_snapshot,warehouse_code_snapshot,warehouse_name_snapshot,currency,payment_terms_days,expected_delivery_date,supplier_reference,internal_note,supplier_note,subtotal,total,order_date,submitted_at,approved_at,sent_at,cancelled_at,cancellation_reason,created_at,updated_at,version FROM purchase_orders WHERE tenant_id=? AND id=?",(r,n)->new OrderView((UUID)r.getObject(1),r.getString(2),(UUID)r.getObject(3),(UUID)r.getObject(4),r.getString(5),r.getString(6),r.getString(7),r.getString(8),r.getString(9),r.getString(10),r.getString(11),(Integer)r.getObject(12),local(r.getDate(13)),r.getString(14),r.getString(15),r.getString(16),r.getBigDecimal(17),r.getBigDecimal(18),local(r.getDate(19)),instant(r.getTimestamp(20)),instant(r.getTimestamp(21)),instant(r.getTimestamp(22)),instant(r.getTimestamp(23)),r.getString(24),r.getTimestamp(25).toInstant(),r.getTimestamp(26).toInstant(),r.getLong(27),lines(t,id)),t,id);if(x.isEmpty())throw err("PURCHASE_ORDER_NOT_FOUND","Purchase order not found");return x.getFirst();}private List<LineView>lines(UUID t,UUID po){return db.query("SELECT id,line_number,supplier_product_id,variant_id,supplier_sku_snapshot,variant_sku_snapshot,description_snapshot,ordered_quantity,purchase_unit_code,base_units_per_purchase_unit,base_quantity,unit_cost,currency,line_subtotal,expected_delivery_date,version FROM purchase_order_lines WHERE tenant_id=? AND purchase_order_id=? ORDER BY line_number",(r,n)->new LineView((UUID)r.getObject(1),r.getInt(2),(UUID)r.getObject(3),(UUID)r.getObject(4),r.getString(5),r.getString(6),r.getString(7),r.getBigDecimal(8),r.getString(9),r.getBigDecimal(10),r.getBigDecimal(11),r.getBigDecimal(12),r.getString(13),r.getBigDecimal(14),local(r.getDate(15)),r.getLong(16)),t,po);}private LineView line(UUID t,UUID po,UUID id){return lines(t,po).stream().filter(l->l.id.equals(id)).findFirst().orElseThrow(()->err("PURCHASE_ORDER_LINE_NOT_FOUND","Line not found"));}private void totals(UUID t,UUID id){db.update("UPDATE purchase_orders SET subtotal=(SELECT COALESCE(sum(line_subtotal),0) FROM purchase_order_lines WHERE tenant_id=? AND purchase_order_id=?),total=(SELECT COALESCE(sum(line_subtotal),0) FROM purchase_order_lines WHERE tenant_id=? AND purchase_order_id=?),updated_at=now(),version=version+1 WHERE tenant_id=? AND id=?",t,id,t,id,t,id);}private SupplierRow supplier(UUID t,UUID id){var x=db.query("SELECT id,supplier_number,name,legal_name,status,default_currency,payment_terms_days FROM suppliers WHERE tenant_id=? AND id=?",(r,n)->new SupplierRow((UUID)r.getObject(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5),r.getString(6),(Integer)r.getObject(7)),t,id);if(x.isEmpty())throw err("SUPPLIER_NOT_PURCHASE_ELIGIBLE","Supplier not found");return x.getFirst();}
 private static BigDecimal positive(String x,String code){try{BigDecimal v=new BigDecimal(x).setScale(6,RoundingMode.UNNECESSARY);if(v.signum()<=0)throw new Exception();return v;}catch(Exception e){throw err(code,"Positive exact quantity required");}}private static BigDecimal scale(BigDecimal x){try{return x.setScale(6,RoundingMode.UNNECESSARY);}catch(Exception e){throw err("INVALID_PURCHASE_QUANTITY","Quantity exceeds supported precision");}}private static BigDecimal money(BigDecimal x){return x.setScale(6,RoundingMode.HALF_UP);}private static String currency(String x){try{return Currency.getInstance(x.trim().toUpperCase()).getCurrencyCode();}catch(Exception e){throw err("PURCHASE_ORDER_CURRENCY_MISMATCH","Invalid ISO currency");}}private static String text(String x,int max){if(x==null)return null;String y=x.trim();if(y.length()>max)throw err("INVALID_PURCHASE_ORDER_DATA","Value too long");return y.isEmpty()?null:y;}private static String required(String x,int max){String y=text(x,max);if(y==null)throw err("INVALID_CANCELLATION_REASON","Cancellation reason required");return y;}private static LocalDate date(LocalDate x){return x;}private static LocalDate local(Date x){return x==null?null:x.toLocalDate();}private static Instant instant(Timestamp x){return x==null?null:x.toInstant();}private static void changed(int n){if(n!=1)throw err("CONCURRENT_MODIFICATION","Purchase order was modified or transition is invalid");}private static ProcurementException err(String c,String m){return new ProcurementException(c,m);}
 record Create(UUID supplierId,UUID warehouseId,String currency,LocalDate expectedDeliveryDate,String supplierReference,String internalNote,String supplierNote){}record Update(UUID warehouseId,LocalDate expectedDeliveryDate,String supplierReference,String internalNote,String supplierNote){}record LineCommand(UUID supplierProductId,String orderedQuantity,LocalDate expectedDeliveryDate){}record LineUpdate(String orderedQuantity,LocalDate expectedDeliveryDate){}record SupplierRow(UUID id,String number,String name,String legalName,String status,String currency,Integer paymentTerms){}record OrderView(UUID id,String number,UUID supplierId,UUID warehouseId,String status,String supplierNumber,String supplierName,String supplierLegalName,String warehouseCode,String warehouseName,String currency,Integer paymentTermsDays,LocalDate expectedDeliveryDate,String supplierReference,String internalNote,String supplierNote,BigDecimal subtotal,BigDecimal total,LocalDate orderDate,Instant submittedAt,Instant approvedAt,Instant sentAt,Instant cancelledAt,String cancellationReason,Instant createdAt,Instant updatedAt,long version,List<LineView>lines){}record LineView(UUID id,int lineNumber,UUID supplierProductId,UUID variantId,String supplierSku,String variantSku,String description,BigDecimal orderedQuantity,String purchaseUnitCode,BigDecimal baseUnitsPerPurchaseUnit,BigDecimal baseQuantity,BigDecimal unitCost,String currency,BigDecimal lineSubtotal,LocalDate expectedDeliveryDate,long version){String baseUnit(){return "EA";}}
}
